import time
import threading
from hatchet_sdk import Hatchet, Context

hatchet = Hatchet()

@hatchet.workflow(on_events=["diamond:create"])
class DiamondWorkflow:
    @hatchet.task()
    def start(self, ctx: Context):
        return {"value": 10}

    @hatchet.task(parents=["start"])
    def branch_a(self, ctx: Context):
        start_output = ctx.workflow_input() # Or ctx.task_output("start")
        # According to Hatchet docs, to get parent output:
        start_val = ctx.task_output("start")["value"]
        return {"a": start_val * 2}

    @hatchet.task(parents=["start"])
    def branch_b(self, ctx: Context):
        start_val = ctx.task_output("start")["value"]
        return {"b": start_val + 5}

    @hatchet.task(parents=["branch_a", "branch_b"])
    def merge(self, ctx: Context):
        a_val = ctx.task_output("branch_a")["a"]
        b_val = ctx.task_output("branch_b")["b"]
        return {"sum": a_val + b_val}

def run_worker():
    worker = hatchet.worker("diamond-worker")
    worker.register_workflow(DiamondWorkflow())
    worker.start()

if __name__ == "__main__":
    # Start worker in a background thread
    worker_thread = threading.Thread(target=run_worker, daemon=True)
    worker_thread.start()

    # Give worker a moment to start
    time.sleep(5)

    print("Triggering workflow...")
    run_id = hatchet.client.admin.run_workflow("DiamondWorkflow", {})

    print(f"Workflow triggered with run ID: {run_id}")

    # Wait for the workflow to complete and get the result
    # In newer SDKs, we can use listener or poll for result
    # For simplicity in this script, we'll poll for the merge task output

