    timeout = 60
    start_time = time.time()

    while time.time() - start_time < timeout:
        try:
            # We want the output of the 'merge' task
            # Note: The SDK might have a more direct way, but polling the run result is common
            run_result = hatchet.client.listener.on_workflow_run(run_id)
            for event in run_result:
                if event.type == "WORKFLOW_RUN_EVENT_FINISHED":
                    # The workflow finished, now we need to get the merge task output
                    # Actually, on_workflow_run might return the final output if defined
                    # But let's be sure and fetch the specific task output if possible
                    # Or just check the event data
                    pass

            # Alternatively, use the synchronous trigger if available
            # result = hatchet.client.admin.run_workflow_sync("DiamondWorkflow", {})
            # However, run_workflow_sync is often preferred for scripts
            break
        except Exception as e:
            print(f"Waiting... {e}")
            time.sleep(2)

    # Let's try the synchronous approach which is cleaner for scripts

