    try:
        # result() waits for the workflow to complete
        # In Hatchet v1, workflow_run.result() might return the final task output
        result_data = workflow_run.result()
    except Exception as e:
        print(f"Error waiting for workflow: {e}")

    if result_data:
        print(f"Workflow completed. Result: {result_data}")
        # The result might be a dictionary of task outputs or just the last task output
        # If it's a dict, we want the 'merge' task's output
        if isinstance(result_data, dict) and "merge" in result_data:
            final_result = result_data["merge"]
        else:
            final_result = result_data

        with open("/tmp/result.json", "w") as f:
            json.dump(final_result, f)
        print("Result written to /tmp/result.json")
    else:
        print("Failed to get workflow result.")

